INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Couch to 5K Reset', 'A nine week on-ramp for anyone coming back from a long layoff. Three easy runs a week, walk breaks built in, and a strict rule against chasing pace before week six.', 'CARDIO', 'BEGINNER', 9, 3, id, TRUE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.m';
INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Barbell Base Builder', 'Linear progression on the squat, bench, deadlift and press. Two upper and two lower sessions a week, with a deload written into every fourth week so the progression actually holds.', 'STRENGTH', 'INTERMEDIATE', 12, 4, id, TRUE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.b';
INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Twenty Minute Metcon', 'Short, brutal conditioning for weeks when the calendar wins. Five sessions a week that never run past twenty minutes, rotating between bike, rower and bodyweight circuits.', 'HIIT', 'ADVANCED', 6, 5, id, TRUE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.b';
INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Desk Body Mobility', 'A daily ten minute mobility habit aimed squarely at hips, thoracic spine and shoulders. Designed to be done in normal clothes without a mat, so the excuse budget stays at zero.', 'FLEXIBILITY', 'BEGINNER', 4, 6, id, TRUE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.m';
INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Off Season Court Prep', 'Eight weeks of change-of-direction work, plyometrics and small sided games for basketball and volleyball players heading into a season.', 'SPORTS', 'INTERMEDIATE', 8, 4, id, TRUE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.b';
INSERT INTO programs (name, description, focus, difficulty, duration_weeks, sessions_per_week, coach_id, published, created_at) SELECT 'Peak Week Taper', 'A one week template for the days before a goal race. Volume drops, intensity stays, and the sleep and fuelling checklist matters more than the training.', 'CARDIO', 'ADVANCED', 1, 4, id, FALSE, DATEADD('DAY', -60, CURRENT_TIMESTAMP) FROM users WHERE username = 'coach.m';
